359	class FileError(Exception):
360	    """文件级错误：整份文件拒绝导入（HTTP 400）。"""
361	
362	
363	class BatchUpdateError(Exception):
364	    """批量修改请求级错误：整次修改拒绝（HTTP 400）。"""
365	
366	
367	FIELD_LABELS = {
368	    "source": "来源",
369	    "region": "地区",
370	    "industry": "行业",
371	    "important_date": "重要日期",
372	}
373	
374	
375	def _normalize_set_value(field_name, value):
376	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
377	
378	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
379	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
380	    """
381	    if not isinstance(value, str):
382	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
383	    text = value.strip()
384	    if not text:
385	        return None
386	    if field_name == "important_date":
387	        ok, reason = check_date(text)
388	        if not ok:
389	            raise BatchUpdateError(reason)
390	    return text
391	
392	
393	def batch_update_clients(database, payload):
394	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
395	
396	    任一问题都整次拒绝，不写入任何客户。
397	    """
398	    if not isinstance(payload, dict):
399	        raise BatchUpdateError("请求体必须是 JSON 对象")
400	
401	    raw_ids = payload.get("ids")
402	    if not isinstance(raw_ids, list):
403	        raise BatchUpdateError("ids 必须是客户编号数组")
404	    if not raw_ids:
405	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
406	
407	    ids = []
408	    seen_ids = set()
409	    for raw_id in raw_ids:
410	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
411	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
412	        if raw_id not in seen_ids:
413	            seen_ids.add(raw_id)
414	            ids.append(raw_id)
415	
416	    raw_updates = payload.get("updates", {})
417	    if not isinstance(raw_updates, dict):
418	        raise BatchUpdateError("updates 必须是字段修改说明对象")
419	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
420	    if extra:
421	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
422	
423	    actions = {}
424	    for field_name in OPTIONAL_FIELDS:
425	        spec = raw_updates.get(field_name, {"op": "keep"})
426	        if not isinstance(spec, dict):
427	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
428	        op = spec.get("op")
429	        if op not in ("keep", "set", "clear"):
430	            raise BatchUpdateError(
431	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
432	        if op == "keep":
433	            continue
434	        if op == "clear":
435	            actions[field_name] = None
436	        else:
437	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
438	
439	    if not actions:
440	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
441	
442	    placeholders = ",".join("?" for _ in ids)
443	    existing = {
444	        row[0]
445	        for row in database.execute(
446	            "SELECT id FROM clients WHERE id IN (%s)" % placeholders, ids
447	        )
448	    }
449	    missing = [cid for cid in ids if cid not in existing]
450	    if missing:
451	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
452	
453	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
454	    params = list(actions.values()) + ids
455	    try:
456	        database.execute(
457	            "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders), params
458	        )
459	        database.commit()
460	    except sqlite3.DatabaseError:
461	        database.rollback()
462	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
463	
464	    return {"updated_count": len(ids)}
465	
