467	def parse_csv(text):
468	    """解析 RFC 4180 风格 CSV，返回 (header, data_rows)。
469	
470	    支持引号包裹的字段、引号内逗号与换行、双引号转义；
471	    引号外支持 LF / CRLF / CR 换行。结构损坏时抛 FileError：
472	    - 未加引号的字段中出现双引号（双引号只能在字段开头用于包住整个字段）；
473	    - 结束引号后出现逗号、换行或文件结束以外的字符（含空格）；
474	    - 文件结束时仍有字段处于引号内（引号未闭合）。
475	    错误信息区分上述三种情况，并指出发生在表头还是第 N 条数据记录
476	    （数据记录编号不包含表头，引号字段内的换行不增加编号）。
477	    """
478	    rows = []
479	    record = []
480	    field = []
481	    quoted = False        # 当前字段处于引号内
482	    started = False       # 当前字段已经开始（已有内容或已进入引号）
483	    closed = False       # 引号字段刚结束，等待逗号 / 换行 / 文件结束
484	    record_number = 0     # 0 = 表头，1 起为数据记录
485	    i = 0
486	    n = len(text)
487	
488	    def location():
489	        return "表头" if record_number == 0 else "第 %d 条数据记录" % record_number
490	
491	    def structure_error(kind):
492	        raise FileError("CSV 结构损坏（%s）：%s" % (location(), kind))
493	
494	    def finish_record():
495	        nonlocal record, field, started, closed
496	        record.append("".join(field))
497	        rows.append(record)
498	        record = []
499	        field = []
500	        started = False
501	        closed = False
502	
503	    while i < n:
504	        c = text[i]
505	        if quoted:
506	            if c == '"':
507	                if i + 1 < n and text[i + 1] == '"':
508	                    field.append('"')
509	                    i += 2
510	                    continue
511	                quoted = False
512	                closed = True
513	                i += 1
514	                continue
515	            if c == "\r":
516	                # 统一字段内换行符为 LF
517	                if i + 1 < n and text[i + 1] == "\n":
518	                    i += 1
519	                field.append("\n")
520	                i += 1
521	                continue
522	            field.append(c)
523	            i += 1
524	            continue
525	        if closed:
526	            # 引号已结束，只允许逗号、记录换行或文件结束
527	            if c == ",":
528	                record.append("".join(field))
529	                field = []
530	                started = False
531	                closed = False
532	            elif c in "\r\n":
533	                if c == "\r" and i + 1 < n and text[i + 1] == "\n":
534	                    i += 1
535	                finish_record()
536	                record_number += 1
537	            else:
538	                structure_error("结束引号后有多余字符，结束引号后只能紧接逗号、记录换行或文件结束")
539	            i += 1
540	            continue
541	        if c == '"' and not started:
542	            quoted = True
543	            started = True
544	        elif c == '"':
545	            structure_error("未加引号的字段中出现双引号，双引号只能在字段开头用于包住整个字段")
546	        elif c == ",":
547	            record.append("".join(field))
548	            field = []
549	            started = False
550	        elif c in "\r\n":
551	            if c == "\r" and i + 1 < n and text[i + 1] == "\n":
552	                i += 1
553	            if not started and not record and not field:
554	                # 空白行：不作为数据记录（显式的 "" 空字段 started=True，仍会保留）
555	                i += 1
556	                continue
557	            finish_record()
558	            record_number += 1
559	        else:
560	            field.append(c)
561	            started = True
562	        i += 1
563	    if quoted:
564	        structure_error("引号未闭合，文件结束时仍有字段处于引号内")
565	    if started or field or record or closed:
566	        record.append("".join(field))
567	        rows.append(record)
568	    if not rows:
569	        raise FileError("CSV 内容为空：缺少表头")
570	    return rows[0], rows[1:]
571	
572	
573	def check_date(value):
574	    """校验 YYYY-MM-DD 且为真实日历日期，返回 (是否合法, 错误原因)。"""
575	    match = DATE_RE.match(value)
576	    if not match:
577	        return False, "重要日期格式无效（%s）：须为 YYYY-MM-DD" % value
578	    try:
579	        datetime.date(int(match.group(1)), int(match.group(2)), int(match.group(3)))
580	    except ValueError:
581	        return False, "重要日期无效（%s）：不是真实日历日期" % value
582	    return True, None
583	
584	
585	def import_clients(database, text):
586	    """执行导入，返回响应字典；文件级错误抛 FileError。"""
587	    header, data_rows = parse_csv(text)
588	    headers = [h.strip() for h in header]
589	
590	    seen = set()
591	    duplicates = []
592	    for h in headers:
593	        if h in seen and h not in duplicates:
594	            duplicates.append(h)
595	        seen.add(h)
596	    if duplicates:
597	        raise FileError("表头重复：%s" % "、".join(repr(h) for h in duplicates))
598	    unknown = [h for h in headers if h not in ALL_COLUMNS]
599	    if unknown:
600	        raise FileError("出现未知列：%s" % "、".join(repr(h) for h in unknown))
601	    if "name" not in headers:
602	        raise FileError("缺少名称列：表头必须包含 name 列")
603	
604	    index = {h: i for i, h in enumerate(headers)}
605	    name_index = index["name"]
606	    date_index = index.get("important_date")
607	
608	    existing = {}
609	    for cid, cname in database.execute("SELECT id, name FROM clients"):
610	        existing[(cname or "").strip().casefold()] = cid
611	
612	    imported = []
613	    failures = []
614	    seen_in_file = {}
615	
616	    for row_number, raw in enumerate(data_rows, start=1):
617	        if len(raw) != len(headers):
618	            failures.append({
619	                "row": row_number,
620	                "reason": "列数不符：表头有 %d 列，该记录有 %d 列" % (len(headers), len(raw)),
621	            })
622	            continue
623	
624	        name = raw[name_index].strip()
625	        problems = []
626	        if not name:
627	            problems.append("缺少名称：name 列为空")
628	        date_value = ""
629	        if date_index is not None:
630	            date_value = raw[date_index].strip()
631	            if date_value:
632	                ok, reason = check_date(date_value)
633	                if not ok:
634	                    problems.append(reason)
635	        if problems:
636	            failures.append({"row": row_number, "reason": "；".join(problems)})
637	            continue
638	
639	        key = name.casefold()
640	        if key in existing:
641	            failures.append({
642	                "row": row_number,
643	                "reason": "名称与已有客户重复（已有客户编号 %d），未更新" % existing[key],
644	            })
645	            continue
646	        if key in seen_in_file:
647	            failures.append({
648	                "row": row_number,
649	                "reason": "名称与文件内第 %d 条记录重复" % seen_in_file[key],
650	            })
651	            continue
652	
653	        seen_in_file[key] = row_number
654	        record = {"name": name}
655	        for field_name in OPTIONAL_FIELDS:
656	            idx = index.get(field_name)
657	            value = raw[idx].strip() if idx is not None else ""
658	            record[field_name] = value or None
659	        imported.append((row_number, record))
660	
661	    saved = []
662	    for row_number, record in imported:
663	        cursor = database.execute(
664	            "INSERT INTO clients (name, source, region, industry, important_date)"
665	            " VALUES (:name, :source, :region, :industry, :important_date)",
666	            record,
667	        )
668	        saved.append({"row": row_number, "id": cursor.lastrowid, "name": record["name"]})
669	    database.commit()
670	
671	    return {
672	        "imported_count": len(saved),
673	        "failed_count": len(failures),
674	        "imported": saved,
675	        "failures": failures,
676	    }
677	
678	
679	def main():
680	    parser = argparse.ArgumentParser(description="ClientBook - 客户联系人与商机记录")
681	    commands = parser.add_subparsers(dest="command", required=True)
682	    serve = commands.add_parser("serve", help="Start the HTTP service")
683	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
684	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
685	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
686	    args = parser.parse_args()
687	    if not 0 <= args.port <= 65535:
688	        parser.error("port must be between 0 and 65535")
689	    args.data_dir.mkdir(parents=True, exist_ok=True)
690	    database = sqlite3.connect(args.data_dir / "client-book.sqlite")
691	    database.execute("CREATE TABLE IF NOT EXISTS clients (id INTEGER PRIMARY KEY, name TEXT NOT NULL)")
692	    columns = {row[1] for row in database.execute("PRAGMA table_info(clients)")}
693	    for field_name in OPTIONAL_FIELDS:
694	        if field_name not in columns:
695	            database.execute("ALTER TABLE clients ADD COLUMN %s TEXT" % field_name)
696	    database.commit()
697	
698	    class Handler(BaseHTTPRequestHandler):
699	        def respond(self, status, value, *, html=False, allow=None):
700	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
701	            self.send_response(status)
702	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
703	            self.send_header("Content-Length", str(len(payload)))
704	            if status == 405:
705	                self.send_header("Allow", allow or "GET")
706	            self.end_headers()
707	            self.wfile.write(payload)
708	
709	        def handle_import(self):
710	            try:
711	                length = int(self.headers.get("Content-Length") or 0)
712	            except ValueError:
713	                length = 0
714	            if length > MAX_BODY:
715	                self.respond(400, {"error": "文件过大：超过 %d 字节上限" % MAX_BODY})
716	                return
717	            raw_body = self.rfile.read(length) if length > 0 else b""
718	            try:
719	                text = raw_body.decode("utf-8-sig")
720	            except UnicodeDecodeError:
721	                self.respond(400, {"error": "编码错误：文件不是有效的 UTF-8 文本"})
722	                return
723	            try:
724	                result = import_clients(database, text)
725	            except FileError as exc:
726	                database.rollback()
727	                self.respond(400, {"error": str(exc)})
728	                return
729	            self.respond(200, result)
730	
731	        def handle_batch_update(self):
732	            try:
733	                length = int(self.headers.get("Content-Length") or 0)
734	            except ValueError:
735	                length = 0
736	            if length > MAX_BODY:
737	                self.respond(400, {"error": "请求体过大：超过 %d 字节上限" % MAX_BODY})
738	                return
739	            raw_body = self.rfile.read(length) if length > 0 else b""
740	            try:
741	                payload = json.loads(raw_body.decode("utf-8"))
742	            except (UnicodeDecodeError, json.JSONDecodeError):
743	                self.respond(400, {"error": "请求体不是有效的 UTF-8 JSON 对象"})
744	                return
745	            try:
746	                result = batch_update_clients(database, payload)
747	            except BatchUpdateError as exc:
748	                database.rollback()
749	                self.respond(400, {"error": str(exc)})
750	                return
751	            self.respond(200, result)
752	
753	        def route(self):
754	            location = urlsplit(self.path).path
755	            if location not in (
756	                "/", "/health", "/api/clients",
757	                "/api/clients/import", "/api/clients/batch-update",
758	            ):
759	                self.respond(404, {"error": "not found"})
760	                return
761	            if location == "/api/clients/import":
762	                if self.command != "POST":
763	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
764	                    return
765	                self.handle_import()
766	                return
767	            if location == "/api/clients/batch-update":
768	                if self.command != "POST":
769	                    self.respond(405, {"error": "method not allowed"}, allow="POST")
770	                    return
771	                self.handle_batch_update()
772	                return
773	            if self.command != "GET":
774	                self.respond(405, {"error": "method not allowed"}, allow="GET")
775	                return
776	            if location == "/":
777	                self.respond(200, PAGE, html=True)
778	            elif location == "/health":
779	                self.respond(200, {"status": "ok", "product": PRODUCT})
780	            else:
781	                records = [
782	                    {
783	                        "id": row[0],
784	                        "name": row[1],
785	                        "source": row[2],
786	                        "region": row[3],
787	                        "industry": row[4],
788	                        "important_date": row[5],
789	                    }
790	                    for row in database.execute(
791	                        "SELECT id, name, source, region, industry, important_date FROM clients ORDER BY id"
792	                    )
793	                ]
794	                self.respond(200, {RESOURCE: records})
795	
796	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
797	
798	    def stop(_signal, _frame):
799	        raise KeyboardInterrupt
800	
801	    signal.signal(signal.SIGTERM, stop)
802	    server = None
803	    try:
804	        server = HTTPServer((args.host, args.port), Handler)
805	        host, port = server.server_address[:2]
806	        address = f"[{host}]" if ":" in host else host
807	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
808	        server.serve_forever()
809	    except KeyboardInterrupt:
810	        pass
811	    finally:
812	        if server is not None:
813	            server.server_close()
814	        database.close()
815	
816	
817	if __name__ == "__main__":
818	    main()
