// Reproduces the double-submit race against the real page served by app.py.
const fs = require("fs");
const path = require("path");
const { JSDOM } = require(path.join("/tmp/domtest/node_modules/jsdom"));

const html = fs.readFileSync("/tmp/page.html", "utf-8");

function makeHarness(responders) {
  // responders: { clients: () => array, batch: (body) => {status, json}|Promise }
  const requests = [];
  const dom = new JSDOM(html, {
    runScripts: "dangerously",
    pretendToBeVisual: true,
    url: "http://127.0.0.1/",
  });
  const { window } = dom;

  window.fetch = async (url, opts) => {
    if (url === "/api/clients") {
      return {
        ok: true,
        status: 200,
        json: async () => ({ clients: responders.clients() }),
      };
    }
    if (url === "/api/clients/batch-update") {
      requests.push(JSON.parse(opts.body));
      const r = await responders.batch(JSON.parse(opts.body));
      return {
        ok: r.status >= 200 && r.status < 300,
        status: r.status,
        json: async () => r.json,
      };
    }
    throw new Error("unexpected url " + url);
  };

  const $ = id => window.document.getElementById(id);
  const fire = (el, type) =>
    el.dispatchEvent(new window.Event(type, { bubbles: true, cancelable: true }));

  return { window, dom, requests, $, fire };
}

function setOp(card, op, value) {
  card.querySelector(`input[value=${op}]`).checked = true;
  card.querySelector(`input[value=${op}]`).dispatchEvent(
    new window.Event("change", { bubbles: true }));
  if (op === "set") card.querySelector(".bf-value").value = value;
}

let failures = 0;
function check(label, cond, extra) {
  console.log(cond ? "PASS" : "FAIL", label, extra !== undefined ? JSON.stringify(extra) : "");
  if (!cond) failures++;
}

(async () => {
  const clients = [
    { id: 1, name: "甲", source: null, region: null, industry: null, important_date: null },
    { id: 2, name: "乙", source: null, region: null, industry: null, important_date: null },
    { id: 3, name: "丙", source: null, region: null, industry: null, important_date: null },
  ];

  // ---- Scenario A: select 1&2, save; while pending select 3 and submit again ----
  let resolveBatch;
  const batchCalls = [];
  const h = makeHarness({
    clients: () => clients,
    batch: async body => {
      return await new Promise(res => {
        batchCalls.push({ body, res });
        resolveBatch = res;
      });
    },
  });
  await new Promise(r => setTimeout(r, 20)); // let initial loadClients() run

  const rows = () => [...h.window.document.querySelectorAll(".row-check")];
  // check 甲(1) and 乙(2)
  rows()[0].checked = true; h.fire(rows()[0], "change");
  rows()[1].checked = true; h.fire(rows()[1], "change");
  // set source = 展会
  setOp(h.window.document.querySelector('.bf[data-field="source"]'), "set", "展会");

  const submitBtn = h.$("batch-submit");
  check("有选中时按钮可提交", submitBtn.disabled === false);

  // first submit
  h.fire(h.$("batch-form"), "submit");
  await new Promise(r => setTimeout(r, 10));
  check("保存中只发出一次请求", batchCalls.length === 1, batchCalls.length);
  check("第一次请求只含甲乙", JSON.stringify(batchCalls[0].body.ids) === "[1,2]", batchCalls[0].body.ids);
  check("保存中按钮持续禁用", submitBtn.disabled === true);
  check("保存中按钮文案变化", submitBtn.textContent === "正在保存…", submitBtn.textContent);
  check("保存中显示正在保存提示", h.$("batch-report").textContent.includes("正在保存"));

  // while pending: check 丙(3), remove, check-all, resubmit via form
  rows()[2].checked = true; h.fire(rows()[2], "change");
  check("等待中勾选丙不启用按钮", submitBtn.disabled === true);
  // remove 甲 via chip
  h.window.document.querySelector('[data-remove="1"]').click();
  check("等待中移除客户不启用按钮", submitBtn.disabled === true);
  // check-all toggle
  const all = h.$("check-all");
  all.checked = true; h.fire(all, "change");
  check("等待中全选不启用按钮", submitBtn.disabled === true);
  all.checked = false; h.fire(all, "change");
  check("等待中取消全选不启用按钮", submitBtn.disabled === true);
