// Reproduces the double-submit race against the real page served by app.py.
const fs = require("fs");
const path = require("path");
const { JSDOM } = require(path.join("/tmp/domtest/node_modules/jsdom"));

const html = fs.readFileSync("/tmp/page.html", "utf-8");

function makeHarness(responders) {
  // responders: { clients: () => array, batch: (body) => {status, json}|Promise }
  const requests = [];
  const dom = new JSDOM(html, {
    runScripts: "dangerously",
    pretendToBeVisual: true,
    url: "http://127.0.0.1/",
  });
  const { window } = dom;

  window.fetch = async (url, opts) => {
    if (url === "/api/clients") {
      return {
        ok: true,
        status: 200,
        json: async () => ({ clients: responders.clients() }),
      };
    }
    if (url === "/api/clients/batch-update") {
      requests.push(JSON.parse(opts.body));
      const r = await responders.batch(JSON.parse(opts.body));
      return {
        ok: r.status >= 200 && r.status < 300,
        status: r.status,
        json: async () => r.json,
      };
    }
    throw new Error("unexpected url " + url);
  };

  const $ = id => window.document.getElementById(id);
  const fire = (el, type) =>
    el.dispatchEvent(new window.Event(type, { bubbles: true, cancelable: true }));

  return { window, dom, requests, $, fire };
}

function setOp(card, op, value) {
  card.querySelector(`input[value=${op}]`).checked = true;
  card.querySelector(`input[value=${op}]`).dispatchEvent(
    new window.Event("change", { bubbles: true }));
  if (op === "set") card.querySelector(".bf-value").value = value;
}

let failures = 0;
function check(label, cond, extra) {
  console.log(cond ? "PASS" : "FAIL", label, extra !== undefined ? JSON.stringify(extra) : "");
  if (!cond) failures++;
}

