    { id: 2, name: "乙", source: null, region: null, industry: null, important_date: null },
    { id: 3, name: "丙", source: null, region: null, industry: null, important_date: null },
  ];

  // ---- Scenario A: select 1&2, save; while pending select 3 and submit again ----
  let resolveBatch;
  const batchCalls = [];
  const h = makeHarness({
    clients: () => clients,
    batch: async body => {
      return await new Promise(res => {
        batchCalls.push({ body, res });
        resolveBatch = res;
      });
    },
  });
  await new Promise(r => setTimeout(r, 20)); // let initial loadClients() run

  const rows = () => [...h.window.document.querySelectorAll(".row-check")];
  // check 甲(1) and 乙(2)
  rows()[0].checked = true; h.fire(rows()[0], "change");
  rows()[1].checked = true; h.fire(rows()[1], "change");
  // set source = 展会
  setOp(h.window.document.querySelector('.bf[data-field="source"]'), "set", "展会");

  const submitBtn = h.$("batch-submit");
  check("有选中时按钮可提交", submitBtn.disabled === false);

  // first submit
  h.fire(h.$("batch-form"), "submit");
  await new Promise(r => setTimeout(r, 10));
  check("保存中只发出一次请求", batchCalls.length === 1, batchCalls.length);
  check("第一次请求只含甲乙", JSON.stringify(batchCalls[0].body.ids) === "[1,2]", batchCalls[0].body.ids);
