  check("未在本次提交中的丙不受影响", clients[2].source === null);

  // ---- Scenario B: server rejects (bad date) -> retain selection & fields, waiting ends ----
  const h2 = makeHarness({
    clients: () => clients,
    batch: async () => ({ status: 400, json: { error: "重要日期无效（2023-02-29）：不是真实日历日期" } }),
  });
  await new Promise(r => setTimeout(r, 20));
  const rows2 = () => [...h2.window.document.querySelectorAll(".row-check")];
  rows2()[2].checked = true; h2.fire(rows2()[2], "change"); // 丙
  setOp(h2.window.document.querySelector('.bf[data-field="important_date"]'), "set", "2023-02-29");
  const btn2 = h2.$("batch-submit");
  h2.fire(h2.$("batch-form"), "submit");
  await new Promise(r => setTimeout(r, 30));
  check("拒绝后显示具体原因", h2.$("batch-report").textContent.includes("2023-02-29")
    && h2.$("batch-report").textContent.includes("日历"));
  check("拒绝后保留勾选", h2.$("sel-count").textContent === "1");
  const dateCard = h2.window.document.querySelector('.bf[data-field="important_date"]');
  check("拒绝后保留字段操作", dateCard.querySelector("input[value=set]").checked === true);
  check("拒绝后保留填写内容", dateCard.querySelector(".bf-value").value === "2023-02-29");
  check("拒绝后等待结束、可再次主动保存", btn2.disabled === false && btn2.textContent === "保存修改");

  // ---- Scenario C: network failure -> waiting ends, error shown, can retry ----
  const h3 = makeHarness({
    clients: () => clients,
    batch: async () => { throw new TypeError("网络中断"); },
  });
  await new Promise(r => setTimeout(r, 20));
  const rows3 = () => [...h3.window.document.querySelectorAll(".row-check")];
  rows3()[0].checked = true; h3.fire(rows3()[0], "change");
  const btn3 = h3.$("batch-submit");
  h3.fire(h3.$("batch-form"), "submit");
  await new Promise(r => setTimeout(r, 30));
  check("请求失败显示失败提示", h3.$("batch-report").textContent.includes("请求失败"));
  check("失败后等待结束可继续使用", btn3.disabled === false && btn3.textContent === "保存修改");
  // retry works
  h3.fire(h3.$("batch-form"), "submit");
  await new Promise(r => setTimeout(r, 10));
  check("失败后用户可重新主动提交", h3.$("batch-report").textContent.includes("正在保存"));

  console.log(failures === 0 ? "\n全部通过" : `\n${failures} 项失败`);
  process.exit(failures ? 1 : 0);
})().catch(e => { console.error(e); process.exit(2); });

